"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type KeyframesPrimitiveProps = ComponentProps<typeof motion.div>;

export function KeyframesPrimitive({ children, ...props }: KeyframesPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : {opacity: 0.5,x: 0}}
      animate={{opacity: [0.5,1,1],x: [0,28,0]}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 0.72, ease: [0.23, 1, 0.32, 1] }}

    >
      {children}
    </motion.div>
  );
}
